# AI Office v2.5 Part A Intelligence Upgrade Architecture Installer
$ErrorActionPreference = "Stop"
$Repository = "E:\AI\AI-Office"
if (-not (Test-Path -LiteralPath $Repository -PathType Container)) { throw "AI Office repository not found." }
Set-Location $Repository
$Timestamp = Get-Date -Format "yyyyMMdd-HHmmss"
$BackupDirectory = Join-Path $Repository ("workspace\installer-backups\v2.5-part-a-" + $Timestamp)
New-Item -ItemType Directory -Path $BackupDirectory -Force | Out-Null
function Write-EmbeddedFile {
    param([string]$RelativePath,[string]$Base64Content)

    $Destination = Join-Path $Repository $RelativePath
    $Parent = Split-Path -Parent $Destination

    if ($Parent -and -not (Test-Path -LiteralPath $Parent)) {
        New-Item -ItemType Directory -Path $Parent -Force | Out-Null
    }

    if (Test-Path -LiteralPath $Destination -PathType Leaf) {
        $BackupPath = Join-Path $BackupDirectory $RelativePath
        $BackupParent = Split-Path -Parent $BackupPath

        if ($BackupParent -and -not (Test-Path -LiteralPath $BackupParent)) {
            New-Item -ItemType Directory -Path $BackupParent -Force | Out-Null
        }

        Copy-Item -LiteralPath $Destination -Destination $BackupPath -Force
    }

    [IO.File]::WriteAllBytes(
        $Destination,
        [Convert]::FromBase64String($Base64Content)
    )

    Write-Host "[WRITTEN] $RelativePath" -ForegroundColor Green
}
Write-EmbeddedFile -RelativePath "config\intelligence\intelligence-policy.json" -Base64Content ""
Write-EmbeddedFile -RelativePath "config\intelligence\benchmark-suite.json" -Base64Content ""
Write-EmbeddedFile -RelativePath "config\intelligence\model-capability-schema.json" -Base64Content ""
Write-EmbeddedFile -RelativePath "workspace\templates\intelligence-model-capability-template.json" -Base64Content ""
Write-EmbeddedFile -RelativePath "scripts\intelligence\Get-AIOfficeIntelligenceArchitecture.ps1" -Base64Content ""
Write-EmbeddedFile -RelativePath "scripts\intelligence\Get-AIOfficeInstalledModels.ps1" -Base64Content ""
Write-EmbeddedFile -RelativePath "scripts\intelligence\Test-AIOfficeIntelligenceArchitecture.ps1" -Base64Content ""
Write-EmbeddedFile -RelativePath "docs\AI-Office-v2.5-Part-A-Intelligence-Upgrade-Architecture.md" -Base64Content ""
$Scripts = @(
    "E:\AI\AI-Office\scripts\intelligence\Get-AIOfficeIntelligenceArchitecture.ps1",
    "E:\AI\AI-Office\scripts\intelligence\Get-AIOfficeInstalledModels.ps1",
    "E:\AI\AI-Office\scripts\intelligence\Test-AIOfficeIntelligenceArchitecture.ps1"
)
foreach ($Script in $Scripts) {
    $Tokens = $null
    $ParseErrors = $null
    [System.Management.Automation.Language.Parser]::ParseFile($Script,[ref]$Tokens,[ref]$ParseErrors) | Out-Null
    if ($ParseErrors.Count -gt 0) {
        throw ("Syntax error in " + $Script + ": " + (($ParseErrors | ForEach-Object { $_.Message }) -join "; "))
    }
}
Write-Host ""
Write-Host "AI Office v2.5 Part A Intelligence Upgrade Architecture installed successfully." -ForegroundColor Green
Write-Host "The live v2.4 conversational runtime was not modified." -ForegroundColor Cyan
Write-Host "Backups: $BackupDirectory" -ForegroundColor Cyan